using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Media;
namespace MRS;
internal sealed class FrequencyOrganizationWindow:Window
{
 private readonly FrequencyLibrary library;private readonly Action applied;private readonly Guid[] selected;
 private readonly ComboBox layout=new(){ItemsSource=new[]{"Subtype and color code","Known system / site, otherwise subtype / CC","Simple protocol folders","Custom folder / name templates"},SelectedIndex=0},scope=new(){ItemsSource=new[]{"Entire library","Selected entries / folders"},SelectedIndex=0};
 private readonly CheckBox existing=Check("Reorganize existing entries",true),future=Check("Use these rules for future decoder and RF discoveries",true),known=Check("Prefer known system / site when available",true),names=Check("Refresh generated labels; always preserve custom names",true),prune=Check("Remove empty generated folders left behind",true);
 private readonly TextBox folderTemplate=new(){Text="{protocol}/{subtype}/{cc}"},nameTemplate=new(){Text="{protocol} · {identity}"};
 private readonly TextBlock status=new(){Foreground=Brushes.Aquamarine,TextWrapping=TextWrapping.Wrap,Margin=new(0,5,0,5)};private readonly DataGrid changes=new(){IsReadOnly=true,AutoGenerateColumns=false,CanUserAddRows=false,Background=Brushes.White,Foreground=Brushes.Black};private readonly TreeView previewTree=new(){Background=new SolidColorBrush(Color.FromRgb(10,17,27)),Foreground=Brushes.White};private readonly TabControl tabs=new(){Foreground=Brushes.Black};private readonly Button apply;private OrganizationPlan? plan;
 private static CheckBox Check(string title,bool value)=>new(){Content=title,IsChecked=value,Foreground=Brushes.Gainsboro,Margin=new(0,4,0,4)};
 internal FrequencyOrganizationWindow(FrequencyLibrary source,IEnumerable<Guid> selection,Action changed)
 {
  library=source;selected=selection.ToArray();applied=changed;Title="Saving & organization";Width=1160;Height=820;MinWidth=850;MinHeight=650;Background=new SolidColorBrush(Color.FromRgb(15,23,35));Foreground=Brushes.Gainsboro;
  var body=new DockPanel{Margin=new(12)};Content=body;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);body.Children.Add(top);top.Children.Add(new TextBlock{Text="Library: "+library.LibraryPath,TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightSteelBlue});top.Children.Add(new TextBlock{Text=$"Loaded {library.Items.Count(i=>!i.IsFolder)} channels · {library.Items.Count(i=>i.IsFolder)} folders. Check this is the library you intend to reorganize.",TextWrapping=TextWrapping.Wrap});top.Children.Add(status);
  var actions=new WrapPanel();DockPanel.SetDock(actions,Dock.Bottom);body.Children.Add(actions);Button(actions,"Preview changes",GeneratePreview);apply=Button(actions,"Apply reviewed organization",Apply);apply.IsEnabled=false;Button(actions,"Close",Close);body.Children.Add(tabs);
  var settings=new StackPanel{Margin=new(12)};tabs.Items.Add(new TabItem{Header="1 · Choose rules",Content=new ScrollViewer{Content=settings,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}});
  void Field(string label,UIElement control){settings.Children.Add(new TextBlock{Text=label,Foreground=Brushes.LightSteelBlue,Margin=new(0,8,0,3)});settings.Children.Add(control);}
  Field("Layout",layout);Field("Scope for existing entries",scope);foreach(var option in new[]{existing,future,known,names,prune})settings.Children.Add(option);Field("Custom folders (slash separates levels)",folderTemplate);Field("Generated-name template",nameTemplate);
  settings.Children.Add(new TextBlock{Text="Fields: {protocol}, {subtype}, {cc}, {network}, {site}, {area}, {home}, {channel}, {identity}, {frequency}. Missing fields omit that folder level. Example: DMR / Capacity Plus / CC 1. LTR defaults to direct Area/Home-labeled entries. Conventional or unclassified DMR stays separate from Capacity Plus, Connect Plus, Tier III and unclassified Motorola rest signaling.",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightSteelBlue,Margin=new(0,10,0,8)});
  settings.Children.Add(new TextBlock{Text="Organization changes only placement and generated names. Stable IDs, exact frequencies, system scopes, evidence, notes and mappings stay intact. No duplicate merge, radio tuning or website upload. Manual saves and website imports keep their placement until you explicitly reorganize them. Unchecking future rules restores legacy automatic placement. Existing auto-save checkboxes are not enabled by this wizard.",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightSteelBlue});
  var preview=new Grid{Margin=new(4)};preview.ColumnDefinitions.Add(new(){Width=new(330)});preview.ColumnDefinitions.Add(new(){Width=new(6)});preview.ColumnDefinitions.Add(new(){Width=new(1,GridUnitType.Star)});preview.Children.Add(previewTree);Grid.SetColumn(changes,2);preview.Children.Add(changes);tabs.Items.Add(new TabItem{Header="2 · Review tree / moves",Content=preview});foreach(var (title,path,width) in new[]{("Action","Action",110),("MHz","MHz",100),("Entry","Entry",180),("Before","Before",280),("After","After",280),("Detail","Detail",280),("Stable ID","RecordId",250)})changes.Columns.Add(new DataGridTextColumn{Header=title,Binding=new Binding(path),Width=width});
  void FitReview(){if(changes.Columns.Count<5)return;changes.Columns[0].Width=85;changes.Columns[1].Width=90;changes.Columns[2].Width=135;double side=Math.Max(150,(changes.ActualWidth-345)/2);changes.Columns[3].Width=side;changes.Columns[4].Width=side;}changes.SizeChanged+=(_,_)=>FitReview();changes.Loaded+=(_,_)=>FitReview();foreach(var column in changes.Columns.OfType<DataGridTextColumn>()){var text=new Style(typeof(TextBlock));text.Setters.Add(new Setter(TextBlock.TextWrappingProperty,TextWrapping.Wrap));text.Setters.Add(new Setter(TextBlock.ToolTipProperty,column.Binding));column.ElementStyle=text;}
  var rollback=new StackPanel{Margin=new(12)};tabs.Items.Add(new TabItem{Header="Rollback",Content=rollback});rollback.Children.Add(new TextBlock{Text="A full local backup is created before applying. Rollback restores that list and its saving rules only while the library is unchanged since that operation. Later edits block rollback; use the import preview to recover selected records instead.",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightSteelBlue});var backups=new ComboBox{Margin=new(0,12,0,12)};rollback.Children.Add(backups);void RefreshBackups(){backups.ItemsSource=library.OrganizationBackups();backups.SelectedIndex=0;}RefreshBackups();tabs.SelectionChanged+=(_,e)=>{if(e.OriginalSource==tabs&&tabs.SelectedIndex==2)RefreshBackups();};Button(rollback,"Review and roll back selected backup…",()=>{if(backups.SelectedItem is not string file)throw new IOException("No organization backup is available for this library.");var old=new FrequencyLibrary(file);if(MessageBox.Show(this,$"Restore {old.Items.Count(i=>!i.IsFolder)} channels and their original folders and saving rules from:\n{file}\n\nRollback is blocked if later library edits exist. A backup of the current list is retained.","Review organization rollback",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;library.RollbackOrganization(file);Invalidate();applied();status.Text="Organization rolled back. Original channel identities and saving rules restored.";RefreshBackups();});
  var rules=library.Organization??new();layout.SelectedIndex=rules.Layout switch{"SystemSite"=>1,"Protocol"=>2,"Custom"=>3,_=>0};known.IsChecked=rules.PreferKnownSites;names.IsChecked=rules.RenameGenerated;folderTemplate.Text=rules.FolderTemplate;nameTemplate.Text=rules.NameTemplate;scope.SelectedIndex=selected.Length>0?1:0;
  foreach(var option in new[]{existing,future,known,names,prune}){option.Checked+=(_,_)=>Invalidate();option.Unchecked+=(_,_)=>Invalidate();}layout.SelectionChanged+=(_,_)=>{known.IsEnabled=layout.SelectedIndex==0;folderTemplate.IsEnabled=layout.SelectedIndex==3;Invalidate();};known.IsEnabled=layout.SelectedIndex==0;folderTemplate.IsEnabled=layout.SelectedIndex==3;scope.SelectionChanged+=(_,_)=>Invalidate();folderTemplate.TextChanged+=(_,_)=>Invalidate();nameTemplate.TextChanged+=(_,_)=>Invalidate();status.Text="Choose rules, then preview. Nothing is changed until Apply.";
 }
 private Button Button(Panel parent,string title,Action action){var button=new Button{Content=title,Foreground=Brushes.Black,Padding=new(10,6,10,6),Margin=new(0,5,8,5)};button.Click+=(_,_)=>{try{action();}catch(Exception ex){status.Text=ex.Message;}};parent.Children.Add(button);return button;}
 private void Invalidate(){plan=null;apply.IsEnabled=false;changes.ItemsSource=null;previewTree.Items.Clear();status.Text="Options changed; generate a fresh preview.";}
 internal void GeneratePreview(){var rules=new OrganizationRules(layout.SelectedIndex switch{1=>"SystemSite",2=>"Protocol",3=>"Custom",_=>"SubtypeColor"},known.IsChecked==true,names.IsChecked==true,folderTemplate.Text,nameTemplate.Text);plan=library.PreviewOrganization(rules,scope.SelectedIndex==1?selected:null,existing.IsChecked==true,future.IsChecked==true,prune.IsChecked==true);changes.ItemsSource=plan.Changes;RenderTree(plan.Items);apply.IsEnabled=plan.Changes.Any(c=>c.Action!="Held");tabs.SelectedIndex=1;status.Text=$"Preview only: {plan.Changes.Count(c=>c.Action=="Move / label")} entries change; {plan.Changes.Count(c=>c.Action=="Held")} held; {plan.Changes.Count(c=>c.Action=="Empty folder")} empty generated folders removed. No channels merged or deleted.";}
 private void RenderTree(List<FrequencyItem> items){previewTree.Items.Clear();var folders=new Dictionary<Guid,TreeViewItem>();foreach(var f in items.Where(i=>i.IsFolder))folders[f.Id]=new(){Header=f.Name,Foreground=Brushes.Gainsboro,IsExpanded=f.ParentId==null};foreach(var f in items.Where(i=>i.IsFolder)){if(f.ParentId is {} parent)folders[parent].Items.Add(folders[f.Id]);else previewTree.Items.Add(folders[f.Id]);}foreach(var channel in items.Where(i=>!i.IsFolder)){var row=new TreeViewItem{Header=channel.ToString(),Foreground=Brushes.Gainsboro};if(channel.ParentId is {} parent)folders[parent].Items.Add(row);else previewTree.Items.Add(row);}}
 internal void Apply(){if(plan==null)throw new IOException("Preview this selection first.");var current=plan;string backup=library.ApplyOrganization(current);plan=null;apply.IsEnabled=false;applied();status.Text="Applied reviewed organization. Backup: "+backup;}
 internal void SmokeApply(){scope.SelectedIndex=0;GeneratePreview();if(plan==null||!apply.IsEnabled)throw new IOException("Wizard did not produce an applicable preview");Apply();if(library.Organization==null)throw new IOException("Wizard did not save future organization rules");}
}
